text:
  "dDurationMs": 2903,
  "segs": [ {
    "utf8": "等於從上野駅的Melody開始聊起"
  } ]
}, {
  "tStartMs": 2378592,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "然後聊到我們一起的一些"
  } ]
}, {
  "tStartMs": 2380294,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "阿宅跟光華商場的回憶"
  } ]
}, {
  "tStartMs": 2382196,
  "dDurationMs": 701,
  "segs": [ {
    "utf8": "你覺得啊"
  } ]
}, {
  "tStartMs": 2382897,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "對於像我"
  } ]
}, {
  "tStartMs": 2383798,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "因為我的觀眾"
  } ]
}, {
  "tStartMs": 2384899,
  "dDurationMs": 2586,
  "segs": [ {
    "utf8": "其實可能比我稍微年輕一點"
  } ]
}, {
  "tStartMs": 2387485,
  "dDurationMs": 4204,
  "segs": [ {
    "utf8": "但是大概在35到60歲之間這個世代"
  } ]
}, {
  "tStartMs": 2391689,
  "dDurationMs": 2602,
  "segs": [ {
    "utf8": "你覺得你還有沒有什麼話想對他們說"
  } ]
}, {
  "tStartMs": 2394291,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "你說有什麼話想要跟大家講"
  } ]
}, {
  "tStartMs": 2395693,
  "dDurationMs": 1234,
  "segs": [ {
    "utf8": "對對對"
  } ]
}, {
  "tStartMs": 2396927,
  "dDurationMs": 1318,
  "segs": [ {
    "utf8": "我覺得就是"
  } ]
}, {
  "tStartMs": 2398245,
  "dDurationMs": 1118,
  "segs": [ {
    "utf8": "我一直都強調"
  } ]
}, {
  "tStartMs": 2399363,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "因為最近剛好是"
  } ]
}, {
  "tStartMs": 2400564,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "我們在錄的時候是中秋連假"
  } ]
}, {
  "tStartMs": 2402466,
  "dDurationMs": 1335,
  "segs": [ {
    "utf8": "我剛好昨天有去聽 "
  } ]
}, {
  "tStartMs": 2403801,
  "dDurationMs": 1652,
  "segs": [ {
    "utf8": "隨性的這一個演唱會"
  } ]
}, {
  "tStartMs": 2405453,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "有 我有看到照片"
  } ]
}, {
  "tStartMs": 2406754,
  "dDurationMs": 3704,
  "segs": [ {
    "utf8": "那我就一直覺得就是說"
  } ]
}, {
  "tStartMs": 2410458,
  "dDurationMs": 1167,
  "segs": [ {
    "utf8": "因為節日對我來說 "
  } ]
}, {
  "tStartMs": 2411625,
  "dDurationMs": 835,
  "segs": [ {
    "utf8": "常常是這個樣子"
  } ]
}, {
  "tStartMs": 2412460,
  "dDurationMs": 1901,
  "segs": [ {
    "utf8": "因為我以前有一陣子在國外念書"
  } ]
}, {
  "tStartMs": 2414361,
  "dDurationMs": 751,
  "segs": [ {
    "utf8": "在國外念書的時候"
  } ]
}, {
  "tStartMs": 2415112,
  "dDurationMs": 1452,
  "segs": [ {
    "utf8": " 國外都會過感恩節"
  } ]
}, {
  "tStartMs": 2416564,
  "dDurationMs": 300,
  "segs": [ {
    "utf8": "是"
  } ]
}, {
  "tStartMs": 2416864,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "感恩節就是那種大家團聚的時候"
  } ]
}, {
  "tStartMs": 2418766,
  "dDurationMs": 984,
  "segs": [ {
    "utf8": "你就會特別的 "
  } ]
}, {
  "tStartMs": 2419750,
  "dDurationMs": 1719,
  "segs": [ {
    "utf8": "就是說我人在異鄉"
  } ]
}, {
  "tStartMs": 2421469,
  "dDurationMs": 1051,
  "segs": [ {
    "utf8": "然後我就覺得說 "
  } ]
}, {
  "tStartMs": 2422520,
  "dDurationMs": 1334,
  "segs": [ {
    "utf8": "沒有辦法跟家人相處"
  } ]
}, {
  "tStartMs": 2423854,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "然後像以前聖誕節"
  } ]
}, {
  "tStartMs": 2425756,
  "dDurationMs": 1368,
  "segs": [ {
    "utf8": "然後大家就很開心 "
  } ]
}, {
  "tStartMs": 2427124,
  "dDurationMs": 1635,
  "segs": [ {
    "utf8": "哇 聖誕樹都很開心"
  } ]
}, {
  "tStartMs": 2428759,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "氣氛 節慶氣氛"
  } ]
}, {
  "tStartMs": 2430161,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "那個時候節慶氣氛很High的時候"
  } ]
}, {
  "tStartMs": 2432163,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "我有好幾次就是"
  } ]
}, {
  "tStartMs": 2433164,
  "dDurationMs": 2018,
  "segs": [ {
    "utf8": "因為美國其實街友多 "
  } ]
}, {
  "tStartMs": 2435182,
  "dDurationMs": 1035,
  "segs": [ {
    "utf8": "街友真的多"
  } ]
}, {
  "tStartMs": 2436217,
  "dDurationMs": 1268,
  "segs": [ {
    "utf8": "那你有時候就是去 "
  } ]
}, {
  "tStartMs": 2437485,
  "dDurationMs": 1618,
  "segs": [ {
    "utf8": "去大採買 有沒有"
  } ]
}, {
  "tStartMs": 2439103,
  "dDurationMs": 801,
  "segs": [ {
    "utf8": "買回來之後"
  } ]
}, {
  "tStartMs": 2439904,
  "dDurationMs": 1017,
  "segs": [ {
    "utf8": "然後就看到他們 "
  } ]
}, {
  "tStartMs": 2440921,
  "dDurationMs": 1485,
  "segs": [ {
    "utf8": "有些還抱著自己的小孩"
  } ]
}, {
  "tStartMs": 2442406,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "在外面乞討的時候"
  } ]
}, {
  "tStartMs": 2443607,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "其實那時候你的感覺就是"
  } ]
}, {
  "tStartMs": 2445009,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "這個城市還是很多人是沒有被照顧到"
  } ]
}, {
  "tStartMs": 2447111,
  "dDurationMs": 2602,
  "segs": [ {
    "utf8": "所以拉回來就是我覺得中秋節也是 就是"
  } ]
}, {
  "tStartMs": 2449713,
  "dDurationMs": 801,
  "segs": [ {
    "utf8": "他的確就是一個"
  } ]
}, {
  "tStartMs": 2450514,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "很多人可以回去跟家人烤肉"
  } ]
}, {
  "tStartMs": 2452216,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "但有些人他可能沒有什麼家人"
  } ]
}, {
  "tStartMs": 2454118,
  "dDurationMs": 2085,
  "segs": [ {
    "utf8": "或者說他的家人跟他處不好"
  } ]
}, {
  "tStartMs": 2456203,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "就是我覺得各式各樣"
  } ]
}, {
  "tStartMs": 2457805,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "或者說他因為工作太忙 "
  } ]
}, {
  "tStartMs": 2459006,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "他沒有辦法回去"
  } ]
}, {
  "tStartMs": 2460107,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "其實我覺得每一個人都會有"
  } ]
}, {
  "tStartMs": 2461809,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "他孤單的那個時間點 "
  } ]
}, {
